-- ============================================================
-- 新增 26 个开源工具
-- 用法：Supabase Dashboard → SQL Editor → New query → 粘贴执行
-- 幂等：同名工具已存在时跳过（不会重复插入）
-- ============================================================

INSERT INTO tools
  (name, category, comment, tags, url, download, download_tier, usage, color, "iconUrl", rating, downloads, views, pinned, is_custom)
SELECT * FROM (VALUES
('Neovim', '开发工具', '终端里的编辑器，Vim 的现代重写版。纯键盘操作，启动毫秒级，插件生态比 Vim 强很多，远程服务器上改代码不用离开命令行。', ARRAY['编辑器','终端','开源','跨平台']::text[], 'https://neovim.io/', 'https://github.com/neovim/neovim/releases', 'free', 'Windows 下推荐先用 winget install Neovim.Neovim 装。第一次打开会懵，建议先跟着 :Tutor 走一遍（约 20 分钟）。配置别自己从零写，直接抄一个现成的框架，比如 LazyVim 或 kickstart.nvim。', '#57A143', 'img/tools/Neovim.png', 5, 0, 0, false, false),
('Docker Desktop', '开发工具', '把应用和依赖打包成容器，换台机器照样跑。本地跑数据库、Redis、中间件不用一个个装，一条命令拉起来。', ARRAY['容器','开发环境','开源','跨平台']::text[], 'https://www.docker.com/products/docker-desktop/', 'https://www.docker.com/products/docker-desktop/', 'free', '装完要开 WSL2（Windows 家庭版也能用）。公司项目一般会给一份 docker-compose.yml，cd 到目录执行 docker compose up -d 就能把整套环境跑起来。硬盘不够的话记得定期 docker system prune。', '#FFFFFF', 'img/tools/DockerDesktop.png', 5, 0, 0, false, false),
('Bruno', '开发工具', '离线的 API 调试工具，Postman 的开源替代。请求数据存在你自己电脑的文件夹里，可以跟项目一起进 Git，不会被强制登录云同步。', ARRAY['API','调试','开源','离线']::text[], 'https://www.usebruno.com/', 'https://github.com/usebruno/bruno/releases', 'free', '装好后新建 Collection 时选一个本地文件夹，这个文件夹就是你的「接口文档」。团队协作时直接把它提交到仓库，别人 clone 下来就能用同一套接口和测试环境变量。', '#FFFFFF', 'img/tools/Bruno.png', 5, 0, 0, false, false),
('DBeaver', '开发工具', '一个客户端连所有数据库：MySQL、PostgreSQL、SQLite、Oracle 都行。开源社区版够用，不用再为每种库装一个工具。', ARRAY['数据库','SQL','开源','跨平台']::text[], 'https://dbeaver.io/', 'https://dbeaver.io/download/', 'free', '选社区版（Community）就行，企业版要钱。连 SQLite 只要选「新建连接」→ SQLite → 指向 .db 文件。大表查询默认会卡界面，记得在设置里把「获取大小」调小到 200 行。', '#382923', '', 5, 0, 0, false, false),
('Zed', '开发工具', '用 Rust 写的新编辑器，打开大文件和搜索的速度比 VS Code 快一个量级。原生支持多人实时协作编辑。', ARRAY['编辑器','高性能','开源']::text[], 'https://zed.dev/', 'https://zed.dev/download', 'free', '目前 Windows 版还在完善中，主力平台是 macOS。如果只是想试试它的速度，装完直接拖整个项目目录进去，Ctrl+P 搜文件的响应速度和 VS Code 差别很明显。', '#FFFFFF', 'img/tools/Zed.png', 5, 0, 0, false, false),
('ImageGlass', '效率工具', '轻量看图工具，秒开大图，支持几十种格式（含 WebP、AVIF、HEIC）。比 Windows 自带照片应用快得多，也不会偷偷联网。', ARRAY['看图','轻量','开源']::text[], 'https://imageglass.org/', 'https://github.com/d2phap/ImageGlass/releases', 'free', '装完在设置里把「关联格式」勾上，之后双击图片就归它管。看漫画或长截图时按 F11 全屏、滚轮缩放，比自带应用顺手。', '#0FB9E8', '', 5, 0, 0, false, false),
('SumatraPDF', '效率工具', 'Windows 上最快的 PDF 阅读器，安装包 5MB，打开几百页的文档基本是瞬间。还支持 EPUB、漫画压缩包。', ARRAY['PDF','阅读','轻量','开源']::text[], 'https://www.sumatrapdfreader.org/', 'https://www.sumatrapdfreader.org/download-free-pdf-viewer', 'free', '直接下便携版（Portable）解压就能用，不写注册表。看 PDF 时按 Ctrl+滚轮缩放、空格翻页，习惯之后比 Adobe Reader 快很多。', '#E87722', 'img/tools/SumatraPDF.png', 5, 0, 0, false, false),
('QuickLook', '效率工具', '按空格键快速预览文件，跟 macOS 的「快速查看」一样。图片、视频、Office、压缩包、代码都能预览，不用双击打开。', ARRAY['预览','效率','开源']::text[], 'https://github.com/QL-Win/QuickLook', 'https://github.com/QL-Win/QuickLook/releases', 'free', '装完成功后任务栏会多一个图标，选中任意文件按空格即可预览，再按一下关闭。解压版也能用，但自带的 Office 插件需要完整安装。', '#FFFFFF', 'img/tools/QuickLook.png', 5, 0, 0, false, false),
('TrafficMonitor', '效率工具', '把网速、CPU、内存占用显示在任务栏上，一眼看到机器状态。中文界面，可以自己调显示哪些指标。', ARRAY['监控','网速','任务栏','开源']::text[], 'https://github.com/zhongyang219/TrafficMonitor', 'https://github.com/zhongyang219/TrafficMonitor/releases', 'free', '选带「x64」的发布包。第一次运行如果任务栏没显示，右键托盘图标 →「显示任务栏窗口」。想显示显卡温度需要额外打开「硬件监控」并给管理员权限。', '#4CAF50', '', 5, 0, 0, false, false),
('MarkText', '效率工具', '所见即所得的 Markdown 编辑器，左边写右边立刻是排版后的样子。写文档、写笔记不用记语法，导出 PDF 和 HTML 也方便。', ARRAY['Markdown','写作','开源']::text[], 'https://www.marktext.cc/', 'https://github.com/marktext/marktext/releases', 'free', '项目更新较慢，下载最新的 release 包就行。它会把文件直接存成 .md，不锁格式；开「打字机模式」写长文时视线不会往下跑。', '#4FC3F7', 'img/tools/MarkText.png', 5, 0, 0, false, false),
('AutoHotkey', '效率工具', 'Windows 自动化脚本工具，用几行脚本把重复操作变成快捷键。批量改名、一键填表、窗口固定位置都能写。', ARRAY['自动化','脚本','效率','开源']::text[], 'https://www.autohotkey.com/', 'https://www.autohotkey.com/download/', 'free', '认准 v2 版本（v1 语法已经不推荐）。最简单的用法：新建一个 .ahk 文件写两行，比如 ::btw::by the way，双击运行后打字 btw 就会自动展开。', '#334455', 'img/tools/AutoHotkey.png', 5, 0, 0, false, false),
('OBS Studio', '影音工具', '免费开源的录屏和直播软件，游戏录制、教程录制、屏幕共享都靠它。功能比大部分付费软件还全。', ARRAY['录屏','直播','开源','跨平台']::text[], 'https://obsproject.com/', 'https://obsproject.com/download', 'free', '第一次打开会走向导，选「仅录制」即可。想录系统声音要在音频设置里加「音频输出采集」，只录麦克风是收不到电脑声音的。录完的文件在「文件 → 显示录像」里。', '#302E31', 'img/tools/OBSStudio.png', 5, 0, 0, false, false),
('HandBrake', '影音工具', '视频转码压缩神器，把几个 G 的录屏压到几百 M 还看不出画质差别。预设里直接选设备，不用懂参数。', ARRAY['转码','压缩','开源','跨平台']::text[], 'https://handbrake.fr/', 'https://handbrake.fr/downloads.php', 'free', '压录屏用「Fast 1080p30」预设，再把质量 RF 调到 22 左右就够了。批量处理用队列：加进队列后点「开始队列」，睡觉前挂上就行。', '#DF4E2B', 'img/tools/HandBrake.png', 5, 0, 0, false, false),
('Audacity', '影音工具', '音频录制和剪辑的老牌开源工具，去噪音、剪片段、调音量都能做。录播客、处理录音素材够用。', ARRAY['音频','剪辑','开源']::text[], 'https://www.audacityteam.org/', 'https://www.audacityteam.org/download/', 'free', '降噪流程：先选中一段纯背景噪音 →「效果 → 噪音消除 → 获取噪声样本」，再全选 → 噪音消除。别一次降太狠，会把声音削成电子音，分两三次轻降效果更好。', '#0000CC', 'img/tools/Audacity.png', 5, 0, 0, false, false),
('Shotcut', '影音工具', '免费视频剪辑软件，时间线操作，支持 4K 和多轨。做短视频、剪游戏片段不用买会员。', ARRAY['剪辑','视频','开源']::text[], 'https://shotcut.org/', 'https://shotcut.org/download/', 'free', '选便携版解压即用。导入素材后直接拖到时间线，剪开按 S 键（分割）。导出选「H.264 High Profile」，想发抖音就把分辨率设成 1080x1920 竖屏。', '#115c77', 'img/tools/Shotcut.png', 5, 0, 0, false, false),
('Balena Etcher', '系统工具', '三步烧录系统镜像到 U 盘：选镜像、选 U 盘、点烧录。烧完自动校验，不会出现写坏了还不知道的情况。', ARRAY['U盘','烧录','开源','跨平台']::text[], 'https://etcher.balena.io/', 'https://etcher.balena.io/#download-etcher', 'free', '比 Rufus 简单但可定制项少。装 Linux 发行版、树莓派系统用它最省心。注意它会清空整个 U 盘，选盘前确认一下容量别选错。', '#00D4AA', 'img/tools/BalenaEtcher.png', 5, 0, 0, false, false),
('Czkawka', '系统工具', '找重复文件、相似图片、空文件夹、坏文件。C 盘爆满时扫一遍，经常能清出几十 G 自己都忘了的老文件。', ARRAY['清理','重复文件','开源','跨平台']::text[], 'https://github.com/qarmin/czkawka', 'https://github.com/qarmin/czkawka/releases', 'free', '下载带 GUI 的版本（czkawka_gui）。先用「重复文件」按内容哈希查，别用文件名——同名不同内容是常事。删之前把文件移到回收站而不是永久删除，留个后悔的余地。', '#4A90E2', 'img/tools/Czkawka.png', 5, 0, 0, false, false),
('Dism++', '系统工具', 'Windows 系统精简和清理工具，能清掉系统盘里那些自带工具清不掉的更新残留、旧驱动备份。也能做系统备份还原。', ARRAY['系统清理','优化','开源']::text[], 'https://github.com/Chuyu-Team/Dism-Multi-language', 'https://github.com/Chuyu-Team/Dism-Multi-language/releases', 'free', '解压即用，不用安装。进「空间回收」先点「扫描」，看清有多少能清再动手。清理 WinSxS 组件库能腾出几个 G，但之后就不能卸载已装的更新了，考虑清楚。', '#6B4FBB', 'img/tools/Dism.png', 5, 0, 0, false, false),
('Motrix', '网络工具', '全能下载器，支持 HTTP、BT、磁力、迅雷链接。界面干净，没有广告和弹窗，最大同时下载数自己设。', ARRAY['下载','BT','开源','跨平台']::text[], 'https://motrix.app/', 'https://github.com/agalwood/Motrix/releases', 'free', 'BT 下载慢的话去「偏好设置 → 进阶」把 tracker 列表填上，速度会明显好转。它基于 aria2，装好后也可以在命令行直接用 aria2c。', '#FF6B6B', '', 5, 0, 0, false, false),
('RustDesk', '网络工具', '开源远程桌面，TeamViewer 的替代品。可以连官方服务器免费用，也能自己搭服务器完全没有连接数限制。', ARRAY['远程桌面','开源','跨平台']::text[], 'https://rustdesk.com/', 'https://github.com/rustdesk/rustdesk/releases', 'free', '帮家人修电脑：让对方装好打开，把界面上的「ID」和「一次性密码」念给你，你输入就能连。官方服务器在国内偶尔慢，自己有服务器的话在设置里改「中继服务器」地址会稳定很多。', '#FFFFFF', 'img/tools/RustDesk.png', 5, 0, 0, false, false),
('WireGuard', '网络工具', '新一代 VPN 协议，配置只有几十行，连接速度比 OpenVPN 快很多。用来把家里的设备连成一个内网特别好用。', ARRAY['VPN','加密','开源']::text[], 'https://www.wireguard.com/', 'https://www.wireguard.com/install/', 'free', 'Windows 装官方客户端，导入 .conf 配置文件就能连。自建的话用 wg-easy 这类带界面的 Docker 镜像，比手写配置文件省事，扫码就能加设备。', '#88171A', 'img/tools/WireGuard.png', 5, 0, 0, false, false),
('Nmap', '网络工具', '网络扫描的行业标准工具。查局域网里有哪些设备在线、开了哪些端口、跑什么服务。运维和安全测试必备。', ARRAY['网络','扫描','安全','开源']::text[], 'https://nmap.org/', 'https://nmap.org/download.html', 'free', '装的时候记得勾上 Npcap（Windows 抓包要用）。最常用的两条：nmap -sn 192.168.1.0/24 扫在线设备；nmap -sV 目标IP 看端口和服务版本。扫别人网络前先确认自己有授权。', '#FFFFFF', 'img/tools/Nmap.png', 5, 0, 0, false, false),
('ComfyUI', 'AI 工具', '节点式 AI 绘图工作流，把模型、采样、放大这些步骤连成一张图。可控性比 WebUI 强，改一个参数就能对比出效果差异。', ARRAY['AI','绘图','工作流','开源']::text[], 'https://www.comfy.org/', 'https://github.com/comfyanonymous/ComfyUI', 'free', '有 NVIDIA 显卡（6G 显存起步）体验最好。官网提供 Windows 一键包，解压双击 run_nvidia_gpu.bat 就会自动装环境。第一次用先跑它自带的默认工作流，能出图了再改节点。', '#FFFFFF', 'img/tools/ComfyUI.png', 5, 0, 0, false, false),
('Open WebUI', 'AI 工具', '给本地大模型套一个 ChatGPT 那样的网页界面。接 Ollama 之后有多轮对话、知识库、模型切换，界面比命令行舒服太多。', ARRAY['AI','大模型','界面','开源']::text[], 'https://openwebui.com/', 'https://github.com/open-webui/open-webui', 'free', '最简单是用 Docker：docker run -d -p 3000:8080 --add-host=host.docker.internal:host-gateway -v open-webui:/app/backend/data ghcr.io/open-webui/open-webui:main。跑起来浏览器开 localhost:3000，第一次注册的账号就是管理员。', '#FFFFFF', 'img/tools/OpenWebUI.png', 5, 0, 0, false, false),
('KoboldCpp', 'AI 工具', '单文件本地大模型推理程序，下载解压就能跑，不用装 Python 环境。支持 GGUF 格式模型，老显卡也能用。', ARRAY['AI','本地推理','开源']::text[], 'https://github.com/LostRuins/koboldcpp', 'https://github.com/LostRuins/koboldcpp/releases', 'free', '下载 koboldcpp.exe 单文件，双击后选一个 GGUF 模型文件就能启动，会自动开浏览器界面。显存不够时把「GPU 层数」调低，剩下的部分用内存跑，速度慢些但能出结果。', '#9C27B0', '', 5, 0, 0, false, false),
('Jellyfin', '影视工具', '自建媒体服务器，把硬盘里的电影剧集整理成 Netflix 那样的界面。自动刮削海报和信息，手机电视都能看。', ARRAY['媒体库','串流','开源','自建']::text[], 'https://jellyfin.org/', 'https://jellyfin.org/downloads/', 'free', 'Windows 装完之后浏览器开 localhost:8096 走初始化向导。影片按「电影名 (年份)/电影名 (年份).mkv」的命名放进去，刮削成功率最高。外网访问用 Tailscale 接入比端口映射安全。', '#FFFFFF', 'img/tools/Jellyfin.png', 5, 0, 0, false, false)
) AS v(name, category, comment, tags, url, download, download_tier, usage, color, iconurl, rating, downloads, views, pinned, is_custom)
WHERE NOT EXISTS (SELECT 1 FROM tools t WHERE t.name = v.name);

-- 检查结果
SELECT count(*) AS total_tools, count(*) FILTER (WHERE is_custom = false) AS builtin FROM tools;
